def word_frequency_analysis(text, search_words):
    # Valid punctuation marks
    valid_punctuation = [
        U+2014,  # EM DASH
        U+2013,  # EN DASH
        U+2018,  # LEFT SINGLE QUOTATION MARK
        U+2019,  # RIGHT SINGLE QUOTATION MARK
        U+201C,  # LEFT DOUBLE QUOTATION MARK
        U+201D,  # RIGHT DOUBLE QUOTATION MARK
        U+2033   # DOUBLE PRIME
    ]

    def is_surrounded_by_punctuation(word):
        start_idx = 0
        end_idx = len(word)
        for char in word:
            code = ord(char)
            if code in valid_punctuation:
                if start_idx == 0:
                    start_idx = 1
                if end_idx == len(word) - 1:
                    end_idx = len(word) - 2
            else:
                break
        return start_idx > 0 and end_idx < len(word) - 1

    result = {}
    for word in search_words:
        if is_surrounded_by_punctuation(word):
            result[word] = text.count(word)
    return result
