    Determines whether the given undirected graph is a tree.

    Args:
        edges (list[tuple[int, int]]): List of undirected edges.

    Returns:
        bool: True if the graph is a tree, False otherwise.
    """
    if len(edges) != len(set(edges)) - 1:
        return False

    # Build adjacency list
    adj = {v: [] for v in set(map(lambda e: e[0] for e in edges)) | set(map(lambda e: e[1] for e in edges))}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check for cycles and connectivity
    visited = set()
    is_connected = True

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in adj.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)

    for v in adj:
        if v not in visited:
            dfs(v)
            if not is_connected:
                return False

    # A tree must have exactly V - 1 edges and be connected
    # Let V be the number of distinct vertices
    vertices = set(adj.keys())
    if len(vertices) == 0:
        return True  # Empty graph with 0 edges is a tree (trivially)
    if len(vertices) == 1:
        return True  # Single vertex with no edges is a tree

    return len(vertices) - 1 == len(edges) and is_connected
