import math

def compute_loss(batch, predictions, confidences):
    """
    Computes position and velocity loss between predicted and actual data.

    Args:
        batch (dict): {instance_id: {'position': [x, y, z], 'velocity': [vx, vy, vz]}}
        predictions (dict): {instance_id: {'position': [x, y, z], 'velocity': [vx, vy, vz]}}
        confidences (dict): {instance_id: float}

    Returns:
        dict: {'avg_position_loss': float, 'avg_velocity_loss': float}
    """
    if not batch or not predictions or not confidences:
        return {'avg_position_loss': 0.0, 'avg_velocity_loss': 0.0}

    position_losses = []
    velocity_losses = []

    for inst_id in set(batch.keys()) & set(predictions.keys()):
        if inst_id not in confidences:
            continue

        actual_pos = batch[inst_id]['position']
        pred_pos = predictions[inst_id]['position']
        actual_vel = batch[inst_id]['velocity']
        pred_vel = predictions[inst_id]['velocity']

        # Position loss: absolute difference between predicted and actual z-positions
        pos_loss = abs(pred_pos[2] - actual_pos[2])

        # Velocity loss: Euclidean distance between predicted and actual 2D velocities
        # Using x and z components as specified
        vel_loss = math.sqrt(
            (pred_vel[0] - actual_vel[0]) ** 2 +
            (pred_vel[2] - actual_vel[2]) ** 2
        )

        position_losses.append(pos_loss)
        velocity_losses.append(vel_loss)

    if position_losses:
        avg_position_loss = sum(position_losses) / len(position_losses)
    else:
        avg_position_loss = 0.0

    if velocity_losses:
        avg_velocity_loss = sum(velocity_losses) / len(velocity_losses)
    else:
        avg_velocity_loss = 0.0

    return {
        'avg_position_loss': avg_position_loss,
        'avg_velocity_loss': avg_velocity_loss
    }
