def matrix_scaled(matrix, scaling_factor):
    # Validate input
    if not isinstance(matrix, list) or not all(isinstance(row, (list, tuple)) for row in matrix):
        raise ValueError("matrix must be a 2D list.")

    if not all(isinstance(elem, (int, float)) for row in matrix for elem in row):
        raise ValueError("All elements in matrix must be integers or floats.")

    if not isinstance(scaling_factor, (int, float)) or scaling_factor == 0:
        raise ValueError("scaling_factor must be a non-zero number.")

    # Check if matrix is rectangular
    if not all(len(row) == len(matrix[0]) for row in matrix):
        raise ValueError("Matrix must be rectangular (all rows have the same length).")

    # Compute scaled matrix
    scaled_matrix = [[round(float(elem) / scaling_factor, 2) for elem in row] for row in matrix]

    # Compute rotated matrix (90 degrees clockwise)
    rotated_matrix = [list(row[::-1]) for row in zip(*matrix)]

    return (scaled_matrix, rotated_matrix)
