def decode_integer(b: bytes, signed: bool) -> int:
    if not b:
        raise ValueError("Input bytes must be non-empty.")

    length = b[0]
    if length < 0 or length > 255:
        raise ValueError("First byte must be a valid length indicator (0-255).")

    if length == 0:
        raise ValueError("Length cannot be zero.")

    # Validate that the remaining bytes can form a number of this length
    if len(b) < length:
        raise ValueError(f"Insufficient bytes to form a {length}-byte integer.")

    # Determine end index
    end = 1 if length == 1 else 2 + length

    # Extract the integer value
    value = int.from_bytes(b[1:end], byteorder='big')

    # Apply signed/unsigned interpretation
    if signed:
        return value
    else:
        return value & ((1 << (8 * length)) - 1)
